param([string]$SshUser = 'root', [string]$KeyPath = (Join-Path $HOME '.ssh/funix_hostinger'))
$ErrorActionPreference = 'Stop'
$report = Join-Path $PSScriptRoot 'funix_hml_prepare_instalacao.txt'
$clientKey = Join-Path $HOME '.ssh/funix_hml_n8n_prepare'
if (-not (Test-Path -LiteralPath $KeyPath)) { throw 'Chave SSH administrativa local nao encontrada.' }
if (-not (Test-Path -LiteralPath $clientKey)) {
    Write-Host 'Criando chave exclusiva do n8n. Defina uma passphrase; guarde-a para a credencial n8n.'
    & ssh-keygen.exe -t ed25519 -f $clientKey -C 'FUNIX-HML-PREPARE'
    if ($LASTEXITCODE -ne 0) { throw 'Falha ao gerar chave.' }
}
if (-not (Test-Path -LiteralPath ($clientKey + '.pub'))) { throw 'Chave publica ausente.' }
Write-Host 'Cole o fine-grained PAT GitHub com Actions e Pull requests somente leitura (entrada oculta). Nao envie o token ao chat.'
$secret = Read-Host -AsSecureString 'GitHub PAT'
$ptr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secret)
try {
    $token = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)
    if ($token -notmatch '^github_pat_[A-Za-z0-9_]{20,240}$') { throw 'Token fora do formato fine-grained esperado.' }
    $payload = @{ public_key = (Get-Content -LiteralPath ($clientKey + '.pub') -Raw).Trim(); token = $token } | ConvertTo-Json -Compress
    $encoded = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($payload))
} finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr); Remove-Variable token,payload -ErrorAction SilentlyContinue; $secret.Dispose() }
$remote = @'
import base64, hashlib, importlib.util, ipaddress, json, os, pathlib, pwd, re, stat, subprocess, sys
P=pathlib.Path
PARAMS='__INPUT__'
CONTROL_B64=''
BASE=P('/usr/local/lib/funix-hml-prepare'); PRIV=P('/var/lib/funix-hml-prepare-control'); HOME=P('/var/lib/funix-hml-ssh-prepare')
USER='funix-hml-prep'; WRAPPER=P('/usr/local/sbin/funix-hml-prepare'); GATE=P('/usr/local/sbin/funix-hml-prepare-ssh'); SUDO=P('/etc/sudoers.d/funix-hml-prepare')
OLD=P('/var/lib/funix-hml/updater/op-44326568450-1-ae33152a5165/po-code-e28bcfda5bb0')
FILES={'hml-update':'6015f365f525fb93be5c3f0f7bf8432379c463c7','hml-update-safety':'ee35bfce1c8c323d5f69cccbb7b493a24cf9ac18','hml-update-transaction':'2d9c7008775f775f3019feb825e38ee4b9b433f9','hml-docker-adapter':'f6cced157db9fc77ac1ef261e968c34371822d41','hml-docker-maintenance':'ec25ab3c3e59cb1bbfbe2627978fa2a01ba830ff','hml-artifact-provenance':'e9b4b13fbcdff8eccd282ba8c5f40bdcbd652464','hml-image-identity':'e3edb166a89c3da458beb60e5f8e778b5c0beb6f','hml-writer-guard':'9c6dccb01e83b2cc6ec9b5d03e3e27486d843334','hml-maintenance':'455e2735efb3596340f21e04ca1036d14981808c','hml-isolation':'d99c222f678e818a08c485f6e85bd20ea93c48d4'}
A=None # REDACTED: historical fixed preparation approval; source-only, do not execute
step='start'
def must(v):
    if not v: raise ValueError('check_failed')
def run(*args): return subprocess.check_output(args,stderr=subprocess.PIPE,text=True,timeout=60).strip()
def out(k,v): print(k,json.dumps(v,ensure_ascii=True),flush=True)
def root_path(path,mode=None):
    s=path.lstat(); must(path.resolve(strict=True)==path and s.st_uid==0 and not(s.st_mode&0o022));
    if mode is not None: must(stat.S_IMODE(s.st_mode)==mode)
    return s
def put(path,data,mode):
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,mode)
    with os.fdopen(fd,'wb') as f: os.fchmod(f.fileno(),mode); f.write(data); f.flush(); os.fsync(f.fileno())
def exists(path): return path.exists() or path.is_symlink()
try:
    os.umask(0o077); must(os.geteuid()==0)
    payload=json.loads(base64.b64decode(PARAMS,validate=True)); must(set(payload)=={'public_key','token'})
    token=payload['token']; must(re.fullmatch(r'github_pat_[A-Za-z0-9_]{20,240}',token) is not None)
    key=payload['public_key'].strip().split(); must(len(key)>=2 and key[0]=='ssh-ed25519' and re.fullmatch(r'[A-Za-z0-9+/=]{40,160}',key[1])); key=' '.join(key[:2])
    sourcebytes=base64.b64decode(CONTROL_B64,validate=True); compile(sourcebytes,'control.py','exec')
    # Validate scope and approved code before making changes.
    step='approved_code'; root_path(OLD,0o700); modules={}
    for name,digest in FILES.items():
        p=OLD/(name+'.py'); s=root_path(p); must(stat.S_ISREG(s.st_mode) and s.st_nlink==1 and not(s.st_mode&0o077)); b=p.read_bytes(); must(hashlib.sha1(('blob '+str(len(b))+'\0').encode()+b).hexdigest()==digest); modules[name]=b
    # Use the prior verified SSH source restriction (one literal internal address only).
    step='origin'; ro=pwd.getpwnam('funix-hml-ro'); auth=P(ro.pw_dir)/'.ssh/authorized_keys'; must(auth.resolve(strict=True)==auth and auth.is_file())
    keys=[x for x in auth.read_text().splitlines() if x.strip() and not x.lstrip().startswith('#')]; must(len(keys)==1)
    matches=re.findall(r'(?:^|,)from="([0-9./]+)"(?=,|\s)',keys[0]); must(len(matches)==1)
    net=ipaddress.ip_network(matches[0],strict=False); must(net.version==4 and net.num_addresses==1 and net.network_address.is_private and not net.network_address.is_loopback); source=str(net.network_address)
    ids=run('docker','ps','-q').split(); must(bool(ids)); rows=json.loads(run('docker','inspect',*ids)); pairs=[]
    for row in rows:
        for n,detail in row.get('NetworkSettings',{}).get('Networks',{}).items():
            if detail.get('IPAddress')==source: pairs.append((row,n))
    must(len(pairs)==1); row,network=pairs[0]; must(re.search(r'(?:^|/)n8n(?:[:@]|$)',row['Config']['Image']) is not None)
    networkdata=json.loads(run('docker','network','inspect',network)); must(len(networkdata)==1 and networkdata[0]['Driver']=='bridge' and set(networkdata[0].get('Containers',{}))=={row['Id']})
    out('ORIGEM',{'restrita':True,'bridge_exclusiva':True,'credencial_leitura_preservada':True})
    # Fail closed on preexisting targets; do not overwrite a local installation.
    step='exclusive_paths'
    for p in [BASE,PRIV,HOME,WRAPPER,GATE,SUDO]: must(not exists(p))
    try: pwd.getpwnam(USER)
    except KeyError: pass
    else: raise ValueError('account_exists')
    for p in [BASE.parent,PRIV.parent,WRAPPER.parent,SUDO.parent]: must(stat.S_ISDIR(root_path(p).st_mode))
    must(P('/usr/bin/sudo').is_file() and P('/usr/bin/python3').is_file() and P('/usr/bin/docker').is_file())
    # Verify API access and exact candidate metadata in memory; token is not printed.
    step='github_metadata'; mod={'__name__':'funix_hml_bootstrap'}; exec(compile(sourcebytes,'control.py','exec'),mod); mod['metadata'](A,token)
    out('GITHUB',{'metadata_ok':True,'artefato':A['identity']['artifact_id'],'sha256':A['digest']})
    # Validate sudoers syntax using a temporary file (not live until all checks pass).
    step='install'; BASE.mkdir(mode=0o700); (BASE/'official').mkdir(mode=0o700); PRIV.mkdir(mode=0o700)
    for name,b in modules.items(): put(BASE/'official'/(name+'.py'),b,0o600)
    put(BASE/'control.py',sourcebytes,0o600); put(PRIV/'approval.json',json.dumps(A,sort_keys=True).encode()+b'\n',0o600); put(PRIV/'github.token',token.encode('ascii')+b'\n',0o600)
    put(WRAPPER,b'#!/bin/sh\nset -eu\n[ "$#" -eq 0 ] || exit 64\nexec /usr/bin/env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin HOME=/root /usr/bin/python3 -I /usr/local/lib/funix-hml-prepare/control.py\n',0o755)
    put(GATE,b'#!/bin/sh\nset -eu\n[ "${SSH_ORIGINAL_COMMAND-}" = "funix-hml-prepare" ] || exit 64\nexec /usr/bin/sudo -n -- /usr/local/sbin/funix-hml-prepare\n',0o755)
    # Create new account, no supplemental groups/password; home and key owned by root.
    step='account'; run('useradd','--system','--user-group','--no-create-home','--home-dir',str(HOME),'--shell','/bin/sh',USER)
    must(run('id','-Gn',USER).split()==[USER]); must(run('passwd','-S',USER).split()[1] in ('L','LK'))
    HOME.mkdir(mode=0o755); os.chmod(HOME,0o755); (HOME/'.ssh').mkdir(mode=0o755); os.chmod(HOME/'.ssh',0o755)
    # No shell or forwarding; SSH source copied only after confirming exclusive current bridge.
    keyline=f'from="{source}",restrict,command="{GATE}" {key} FUNIX-HML-PREPARE\n'
    step='sudo'; tmp=PRIV/'sudoers.check'; put(tmp,(f'{USER} ALL=(root) NOPASSWD: {WRAPPER} ""\n').encode(),0o440)
    run('visudo','-cf',str(tmp)); put(SUDO,tmp.read_bytes(),0o440); tmp.unlink(); run('visudo','-c')
    # Negative check as the service user (no actual preparation).
    step='negative_check'; p=subprocess.run(['runuser','-u',USER,'--','env','SSH_ORIGINAL_COMMAND=whoami',str(GATE)],capture_output=True,timeout=15); must(p.returncode==64 and not p.stdout)
    p=subprocess.run(['runuser','-u',USER,'--','sudo','-n','-l',str(WRAPPER)],capture_output=True,timeout=15); must(p.returncode==0)
    # Publish authorized key LAST, after local restrictions validated.
    step='enable_key'; put(HOME/'.ssh/authorized_keys',keyline.encode('ascii'),0o644)
    out('RESULTADO',{'installed':True,'user':USER,'command':'funix-hml-prepare','authorization':'candidate_fixed','no_shell':True,'no_docker_group':True,'negative_command_rejected':True,'github_token_private':True,'n8n_credential_pending':True,'download':False,'deploy':False})
except Exception as e:
    out('BLOQUEADO',{'step':step,'type':type(e).__name__,'deploy':False,'do_not_repeat_if_partial':True}); sys.exit(1)
 
'@
try {
    $remote = $remote.Replace('__INPUT__', $encoded)
    $OutputEncoding = [Text.Encoding]::ASCII
    $remote | & ssh.exe -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=15 -i $KeyPath "$SshUser@2.25.144.201" 'python3 -u -' 2>&1 | Tee-Object -FilePath $report
    $code = $LASTEXITCODE
    "SSH_EXIT=$code" | Tee-Object -FilePath $report -Append
    Write-Host "Relatorio: $report"
    if ($code -eq 0) { Write-Host "Chave privada LOCAL para a credencial n8n: $clientKey (nao envie ao chat)" }
    if ($code -ne 0) { Write-Host 'Bloqueado: nao repita se houve instalacao parcial. Envie apenas o relatorio.' }
} finally { Remove-Variable remote,encoded -ErrorAction SilentlyContinue }
